steps:
1. Overwrite DCDSS/Program.cs with the full DI and middleware pipeline per design Section 16. Exact registration order matters:

    a) builder.Services.AddControllers(o => o.Filters.Add<AuditActionFilter>());
    b) builder.Services.AddEndpointsApiExplorer();
    c) builder.Services.AddSwaggerGen(c => { c.SwaggerDoc("v1", new OpenApiInfo { Title = "DCDSS API", Version = "v1" }); c.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme { Name = "Authorization", Type = SecuritySchemeType.Http, Scheme = "bearer", BearerFormat = "JWT", In = ParameterLocation.Header, Description = "Enter JWT token" }); c.AddSecurityRequirement(new OpenApiSecurityRequirement { { new OpenApiSecurityScheme { Reference = new OpenApiReference { Type = ReferenceType.SecurityScheme, Id = "Bearer" } }, Array.Empty<string>() } }); });
    d) var conn = builder.Configuration.GetConnectionString("DefaultConnection")!; var serverVersion = new MySqlServerVersion(new Version(8, 0, 34)); builder.Services.AddDbContextFactory<DcdssContext>(o => o.UseMySql(conn, serverVersion));
    e) builder.Services.Configure<JwtSettings>(builder.Configuration.GetSection("JwtSettings")); builder.Services.Configure<CorsSettings>(builder.Configuration.GetSection("CorsSettings")); builder.Services.Configure<AdminSeedSettings>(builder.Configuration.GetSection("AdminSeed")); builder.Services.AddSingleton<IValidateOptions<JwtSettings>, JwtSettingsValidator>(); builder.Services.AddOptions<JwtSettings>().Bind(builder.Configuration.GetSection("JwtSettings")).ValidateOnStart();
    f) Read JwtSettings for token validation params — use builder.Configuration.GetSection("JwtSettings").Get<JwtSettings>()! (note: ValidateOnStart fires at build time, so reading here before Build() is fine for wiring, but the validator fires later; alternatively bind inline in AddJwtBearer). builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => { var jwt = builder.Configuration.GetSection("JwtSettings").Get<JwtSettings>()!; o.TokenValidationParameters = new TokenValidationParameters { ValidateIssuer=true, ValidateAudience=true, ValidateLifetime=true, ValidateIssuerSigningKey=true, ValidIssuer=jwt.Issuer, ValidAudience=jwt.Audience, IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.SigningKey)), ClockSkew=TimeSpan.FromMinutes(1), NameClaimType="name", RoleClaimType="role" }; });
    g) builder.Services.AddAuthorization(o => o.FallbackPolicy = new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build());
    h) CORS: var cors = builder.Configuration.GetSection("CorsSettings").Get<CorsSettings>()!; builder.Services.AddCors(o => o.AddPolicy("Default", b => b.WithOrigins(cors.AllowedOrigins.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)).AllowAnyHeader().AllowAnyMethod()));
    i) builder.Services.AddHealthChecks().AddDbContextCheck<DcdssContext>();
    j) builder.Services.AddHttpContextAccessor();
    k) Repositories (Scoped): AddScoped<IUserRepository, UserRepository>; AddScoped<IPatientRepository, PatientRepository>; AddScoped<IPatientAllergyRepository, PatientAllergyRepository>; AddScoped<IMedicalRecordRepository, MedicalRecordRepository>; AddScoped<ILabResultRepository, LabResultRepository>; AddScoped<IMedicationRepository, MedicationRepository>; AddScoped<IAppointmentRepository, AppointmentRepository>; AddScoped<IAuditLogRepository, AuditLogRepository>; AddScoped<IUnitOfWork, UnitOfWork>; AddScoped(typeof(IRepository<>), typeof(Repository<>));
    l) Services (Scoped): AddScoped<IAuthService, AuthService>; AddScoped<IPatientService, PatientService>; AddScoped<IMedicalRecordService, MedicalRecordService>; AddScoped<ILabService, LabService>; AddScoped<IMedicationService, MedicationService>; AddScoped<IAppointmentService, AppointmentService>; AddScoped<IReportService, ReportService>; AddScoped<IAuditLogService, AuditLogService>; AddScoped<ISafetyCheckService, SafetyCheckService>; AddScoped<ICdsEngine, CdsEngine>; AddScoped<IAdminSeeder, AdminSeeder>;
    m) Services (Singleton): AddSingleton<IClinicalRuleStore, ClinicalRuleStore>; AddSingleton<IReferenceRangeParser, ReferenceRangeParser>; AddSingleton<ITokenService, JwtTokenService>; (Note: class is TokenService but if you want to call the class JwtTokenService that is fine — be consistent with what was created in FEAT-002);
    n) AddScoped<ICurrentUserService, CurrentUserService>; AddTransient<PasswordHasher<User>>();

    var app = builder.Build();
    app.UseMiddleware<GlobalExceptionMiddleware>();
    if (!app.Environment.IsDevelopment()) { app.UseHsts(); }
    app.UseHttpsRedirection();
    app.UseCors("Default");
    app.UseAuthentication();
    app.UseAuthorization();
    app.MapHealthChecks("/health");
    app.MapControllers();
    if (app.Environment.IsDevelopment()) { app.UseSwagger(); app.UseSwaggerUI(); }
    using (var scope = app.Services.CreateScope()) { await scope.ServiceProvider.GetRequiredService<IAdminSeeder>().SeedAsync(); }
    app.Run();

    Required usings at top: Microsoft.AspNetCore.Authentication.JwtBearer, Microsoft.AspNetCore.Authorization, Microsoft.AspNetCore.Identity, Microsoft.EntityFrameworkCore, Microsoft.Extensions.Options, Microsoft.IdentityModel.Tokens, Pomelo.EntityFrameworkCore.MySql.Infrastructure, System.Text, DCDSS.Configuration, DCDSS.Data, DCDSS.Entities, DCDSS.Middleware, DCDSS.Repositories, DCDSS.Repositories.Interfaces, DCDSS.Security, DCDSS.Services, DCDSS.Services.Interfaces, Microsoft.OpenApi.Models.

